import { useEffect, useRef, useState } from "react";

export default function ProductSearch() {
  const [query, setQuery] = useState("");
  const [items, setItems] = useState<string[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const requestSequence = useRef(0);

  useEffect(() => {
    const requestId = ++requestSequence.current;
    const keyword = query.trim();

    if (keyword === "") {
      setItems([]);
      setError(null);
      setLoading(false);
      return;
    }

    const controller = new AbortController();
    let active = true;

    const isCurrentRequest = () =>
      active && requestId === requestSequence.current;

    setItems([]);
    setError(null);
    setLoading(true);

    async function searchProducts() {
      try {
        const response = await fetch(
          `/api/products?name=${encodeURIComponent(keyword)}`,
          { signal: controller.signal },
        );

        if (!response.ok) {
          throw new Error(`상품 검색에 실패했습니다. (${response.status})`);
        }

        const products = (await response.json()) as string[];

        if (isCurrentRequest()) {
          setItems(products);
        }
      } catch (caught) {
        if (!isCurrentRequest()) {
          return;
        }

        if (caught instanceof DOMException && caught.name === "AbortError") {
          return;
        }

        setItems([]);
        setError(
          caught instanceof Error
            ? caught.message
            : "상품 검색에 실패했습니다.",
        );
      } finally {
        if (isCurrentRequest()) {
          setLoading(false);
        }
      }
    }

    void searchProducts();

    return () => {
      active = false;
      controller.abort();
    };
  }, [query]);

  return (
    <section>
      <label htmlFor="product-query">상품 검색</label>
      <input
        id="product-query"
        value={query}
        onChange={(event) => setQuery(event.target.value)}
      />

      {loading && <p>검색 중...</p>}
      {error && <p role="alert">{error}</p>}

      <ul>
        {items.map((item) => (
          <li key={item}>{item}</li>
        ))}
      </ul>
    </section>
  );
}

