import re
from collections.abc import Callable


type ConfigValue = int | bool
type Parser = Callable[[str], ConfigValue]

_INTEGER_PATTERN = re.compile(r"[+-]?[0-9]+")
_BOOLEAN_VALUES: dict[str, bool] = {
    "true": True,
    "false": False,
}


def _bounded_integer(minimum: int, maximum: int) -> Parser:
    def parse(value: str) -> int:
        if _INTEGER_PATTERN.fullmatch(value) is None:
            raise ValueError("정수 형식이 아닙니다")

        parsed = int(value, 10)
        if not minimum <= parsed <= maximum:
            raise ValueError("허용 범위를 벗어났습니다")

        return parsed

    return parse


def _boolean(value: str) -> bool:
    try:
        return _BOOLEAN_VALUES[value]
    except KeyError:
        raise ValueError("불리언 형식이 아닙니다") from None


_SPECS: tuple[tuple[str, str, Parser], ...] = (
    ("PORT", "8080", _bounded_integer(1, 65535)),
    ("WORKERS", "4", _bounded_integer(1, 32)),
    ("DEBUG", "false", _boolean),
)


def parse_config(env: dict[str, str]) -> dict[str, ConfigValue]:
    result: dict[str, ConfigValue] = {}
    invalid_fields: list[str] = []

    for field, default, parser in _SPECS:
        raw_value = env.get(field, default).strip()

        try:
            result[field] = parser(raw_value)
        except ValueError:
            invalid_fields.append(field)

    if invalid_fields:
        fields = ", ".join(sorted(invalid_fields))
        raise ValueError(f"잘못된 설정 필드: {fields}")

    return result

def _parse_bounded_int(text: str, minimum: int, maximum: int) -> int | None:
    normalized = text.strip()

    if normalized[:1] in ("+", "-"):
        digits = normalized[1:]
    else:
        digits = normalized

    if not digits or any(char < "0" or char > "9" for char in digits):
        return None

    value = int(normalized, 10)
    if value < minimum or value > maximum:
        return None

    return value


def parse_config(env: dict[str, str]) -> dict:
    result: dict[str, int | bool] = {}
    errors: list[str] = []

    integer_fields = (
        ("PORT", 8080, 1, 65535),
        ("WORKERS", 4, 1, 32),
    )

    for name, default, minimum, maximum in integer_fields:
        if name not in env:
            result[name] = default
            continue

        value = _parse_bounded_int(env[name], minimum, maximum)
        if value is None:
            errors.append(name)
        else:
            result[name] = value

    if "DEBUG" not in env:
        result["DEBUG"] = False
    else:
        debug_text = env["DEBUG"].strip()
        if debug_text == "true":
            result["DEBUG"] = True
        elif debug_text == "false":
            result["DEBUG"] = False
        else:
            errors.append("DEBUG")

    if errors:
        raise ValueError(f"잘못된 설정: {', '.join(sorted(errors))}")

    return result

class LengthPrefixedFrameParser:
    HEADER_SIZE = 4
    MAX_PAYLOAD_SIZE = 1024

    def __init__(self) -> None:
        self._buffer = bytearray()
        self._failed = False

    def feed(self, data: bytes) -> list[bytes]:
        if self._failed:
            raise ValueError("파서가 오류 상태입니다. reset()을 호출해야 합니다.")

        if not isinstance(data, bytes):
            raise TypeError("data는 bytes여야 합니다.")

        self._buffer.extend(data)
        frames: list[bytes] = []
        offset = 0

        while True:
            remaining = len(self._buffer) - offset
            if remaining < self.HEADER_SIZE:
                break

            payload_length = int.from_bytes(
                self._buffer[offset:offset + self.HEADER_SIZE],
                byteorder="big",
                signed=False,
            )

            if payload_length > self.MAX_PAYLOAD_SIZE:
                self._failed = True
                self._buffer.clear()
                raise ValueError(
                    f"허용되지 않은 페이로드 길이입니다: {payload_length}"
                )

            frame_end = offset + self.HEADER_SIZE + payload_length
            if frame_end > len(self._buffer):
                break

            payload_start = offset + self.HEADER_SIZE
            frames.append(bytes(self._buffer[payload_start:frame_end]))
            offset = frame_end

        if offset > 0:
            del self._buffer[:offset]

        return frames

    def reset(self) -> None:
        self._buffer.clear()
        self._failed = False
